const getUserLeaderboardPosition = `-- name: GetUserLeaderboardPosition :one
SELECT
    1 + COUNT(s2.squad_id) AS rank,
    target.user_id,
    target.username,
    target.total_points
FROM (
    SELECT
        u.user_id,
        u.username,
        s.total_points,
        s.squad_id
    FROM squad s
    JOIN users u ON u.user_id = s.user_id
    WHERE u.user_id = $1
    LIMIT 1
) AS target
LEFT JOIN squad s2
    ON s2.total_points > target.total_points
    OR (
        s2.total_points = target.total_points
        AND s2.squad_id < target.squad_id
    )
GROUP BY target.user_id, target.username, target.total_points
`

type GetUserLeaderboardPositionRow struct {
	Rank        int32         `json:"rank"`
	UserID      int32         `json:"user_id"`
	Username    string        `json:"username"`
	TotalPoints sql.NullInt32 `json:"total_points"`
}

func (q *Queries) GetUserLeaderboardPosition(ctx context.Context, userID int32) (GetUserLeaderboardPositionRow, error) {
	row := q.queryRow(ctx, q.getUserLeaderboardPositionStmt, getUserLeaderboardPosition, userID)
	var i GetUserLeaderboardPositionRow
	err := row.Scan(
		&i.Rank,
		&i.UserID,
		&i.Username,
		&i.TotalPoints,
	)
	return i, err
}

