const updatePointsForNation = `-- name: UpdatePointsForNation :exec
UPDATE squad s
SET total_points = total_points + ($1 * (
    SELECT COUNT(*) FROM squad_player sp
    JOIN players p ON sp.player_id = p.player_id
    WHERE sp.squad_id = s.squad_id AND p.nationality_id = $2
))
WHERE EXISTS (
    SELECT 1 FROM squad_player sp
    JOIN players p ON sp.player_id = p.player_id
    WHERE sp.squad_id = s.squad_id AND p.nationality_id = $2
)
`

type UpdatePointsForNationParams struct {
	PlayerID      int32         `json:"player_id"`
	NationalityID sql.NullInt32 `json:"nationality_id"`
}

func (q *Queries) UpdatePointsForNation(ctx context.Context, arg UpdatePointsForNationParams) error {
	_, err := q.exec(ctx, q.updatePointsForNationStmt, updatePointsForNation, arg.PlayerID, arg.NationalityID)
	return err
}

const updateSquadBudget = `-- name: UpdateSquadBudget :one
UPDATE squad
SET budget_used = $2
WHERE squad_id = $1
RETURNING squad_id, user_id, squad_name, formation, budget_used, total_points
`

type UpdateSquadBudgetParams struct {
	SquadID    int32         `json:"squad_id"`
	BudgetUsed sql.NullInt64 `json:"budget_used"`
}

func (q *Queries) UpdateSquadBudget(ctx context.Context, arg UpdateSquadBudgetParams) (Squad, error) {
	row := q.queryRow(ctx, q.updateSquadBudgetStmt, updateSquadBudget, arg.SquadID, arg.BudgetUsed)
	var i Squad
	err := row.Scan(
		&i.SquadID,
		&i.UserID,
		&i.SquadName,
		&i.Formation,
		&i.BudgetUsed,
		&i.TotalPoints,
	)
	return i, err
}

